select 'pools', 'Compass - The Swimming Pool Company', 'Compass - The Swimming Pool Company', 'دبي', 'القوز الصناعية 1', '+971 4 339 0411', 'https://www.compass-me.com/', 1989, 'شركة في دبي لإنشاء المسابح والسبا وصيانتها وتوريد معداتها، تأسست عام 1989.', 'https://www.compass-me.com/', 'تأسست كومباس عام 1989 وتتبع مجموعة وافي، ومقرها منطقة القوز الصناعية 1 في دبي. تعمل عبر أربعة أقسام: مشاريع كومباس، وAquaClear لتعقيم المياه، ومتجر كومباس للمسابح، وخدمة الصيانة Those Pool Guys. تنفذ المسابح والسبا والساونا والنوافير وتقدم خدمة صيانة على مدار الساعة.', 'https://www.compass-me.com/wp-content/uploads/2022/12/logo-with-tagline.webp', 'info@compass-me.com', 'شارع 18، منطقة القوز الصناعية 1، ص.ب 30150، دبي', 'https://www.google.com/maps/place/Compass+Swimming+Pool+Supplies/@25.1467333,55.2381172,19z/data=!4m12!1m6!3m5!1s0x0:0x8d77bc8b0556f862!2sCompass+Those+Pool+Guys!8m2!3d25.1465463!4d55.2393081!3m4!1s0x3e5f69b94bcd4f23:0xef8132be06c15962!8m2!3d25.1466305!4d55.2377129', array['إنشاء المسابح والسبا والساونا والنوافير', 'خدمة الصيانة Those Pool Guys على مدار الساعة', 'أنظمة التعقيم بالملح AquaClear', 'متجر معدات وإكسسوارات المسابح', 'ضمان 10 سنوات على هيكل المسبح']::text[], 'تذكر الشركة أن لديها فريقاً من الفنيين المدربين والمختصين المعتمدين دون ذكر أسماء.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Compass - The Swimming Pool Company'));
