select 'pools', 'Exterior Space Landscape Works', 'Exterior Space Landscape Works', 'دبي', 'الكرامة', '+971 4 256 4151', 'https://exteriorspacedubai.com/', null, 'شركة في دبي لتصميم وإنشاء وتجديد وصيانة المسابح وتنسيق الحدائق للفلل.', 'https://exteriorspacedubai.com/', 'شركة مقرها الكرامة في دبي تعمل في تصميم المسابح وإنشائها وتجديدها وصيانتها إلى جانب تنسيق الحدائق والمساحات الخارجية. تذكر أنها تتولى التصاميم ثلاثية الأبعاد وموافقات بلدية دبي والتنفيذ والصيانة داخلياً.', 'https://exteriorspacedubai.com/wp-content/uploads/2025/06/exterior-logo.png', 'hello@exteriorspacedubai.com', 'مكتب M 01، مبنى أريتي، الكرامة، دبي', null, array['فيلا 233 كايا – المرابع العربية 3', '81 سهيل 1 – المرابع العربية', 'فيلا C19 – قرية جميرا المثلث', 'خدمات المسابح عن بُعد لملاك العقارات بالخارج', 'تنسيق الحدائق والمساحات الخارجية']::text[], 'يضم الفريق معماريين ومصممي حدائق ومهندسين وحرفيين ومديري مشاريع حسب الموقع.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Exterior Space Landscape Works'));
