select 'pools', 'Skylark Pools (Skylark Contracting LLC)', 'Skylark Pools (Skylark Contracting LLC)', 'دبي', 'مجمع دبي للاستثمار 2', '+971 4 296 5232', 'https://skylarkpools.ae/', 2014, 'قسم المسابح في شركة سكايلارك للمقاولات بدبي لتصميم المسابح وإنشائها وتجديدها وصيانتها.', 'https://skylarkpools.ae/', 'سكايلارك بولز قسم تابع لشركة سكايلارك للمقاولات ذ.م.م، تأسست عام 2014 ومعرضها في مجمع دبي للاستثمار 2. تذكر أنها مسجلة لدى بلدية دبي وتراخيص (Trakhees) وسلطة دبي للتطوير. تعمل في تصميم المسابح وإنشائها وتجديدها وصيانتها وأتمتتها إضافة إلى تنسيق الحدائق.', 'https://skylarkpools.ae/wp-content/uploads/2025/10/cropped-cropped-SCLLClogo_whitebg.jpg', 'info@skylarkpools.ae', 'مستودع رقم 3، باركس شوبنغ سنتر، مجمع دبي للاستثمار 2، ص.ب 126600، دبي', null, array['تصميم وإنشاء وتجديد المسابح', 'أتمتة المسابح الذكية', 'الجاكوزي والسبا', 'النوافير والمعالم المائية', 'البرجولات الألمنيوم والتظليل']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Skylark Pools (Skylark Contracting LLC)'));
