select 'pools', 'Hydrolite Leisure L.L.C.', 'Hydrolite Leisure L.L.C.', 'دبي', null, '+971 50 488 1940', 'https://hydrolitepools.com/', 1979, 'شركة تأسست في الشارقة عام 1979 ثم انتقلت إلى دبي، تعمل في إنشاء المسابح والنوافير.', 'https://hydrolitepools.com/About-Us/', 'تأسست هيدرولايت ليجر في الشارقة عام 1979 ثم انتقلت إلى دبي. تعمل في المسابح والنوافير وتنسيق الحدائق والتصميم الداخلي والأعمال الميكانيكية والتكييف، وتذكر أنها تنفذ أعمالها بقوتها العاملة دون مقاولين من الباطن.', 'https://hydrolitepools.com/wp-content/uploads/2026/07/Hydrolite-Finallogo.jpg', 'info@hydrolitepools.com', 'دبي، الإمارات العربية المتحدة', null, array['مسابح ونوافير في ذا ميدوز', 'المرابع العربية', 'تلال الإمارات', 'نخلة جميرا', 'جزر جميرا']::text[], 'تذكر الشركة أنها تعتمد على قوتها العاملة المؤهلة دون التعاقد من الباطن.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'دبي' and lower(coalesce(name_en, name_ar)) = lower('Hydrolite Leisure L.L.C.'));
