select 'pools', 'Hayatt Swimming Pools Maintenance LLC', 'Hayatt Swimming Pools Maintenance LLC', 'أبوظبي', 'مدينة خليفة أ', '+971 600 542928', 'https://hayattpools.ae/', null, 'شركة في أبوظبي لتنظيف المسابح وصيانتها وإصلاح التسربات وعقود الصيانة السنوية.', 'https://hayattpools.ae/about-us/', 'حياة لصيانة المسابح ذ.م.م شركة مقرها مدينة خليفة أ في أبوظبي. تقدم تنظيف المسابح وصيانتها وتجديدها وإصلاح التسربات وعقود الصيانة السنوية وخدمة طوارئ على مدار الساعة.', 'https://hayattpools.ae/wp-content/uploads/2026/05/HSPM-2.webp', 'office@hayattpools.ae', 'مدينة خليفة أ، أبوظبي', 'https://www.google.com/maps/place/Hayatt+Swimming+Pools+Maintenance/@24.3964063,54.5547973,17z/data=!4m6!3m5!1s0x877c823ff0bd3173:0x4c56634b436c899e!8m2!3d24.3970593!4d54.5584916!16s%2Fg%2F11y7bzh2ts', array['تنظيف المسابح', 'تجديد المسابح', 'إصلاح تسربات المسابح', 'صيانة طوارئ على مدار الساعة', 'عقود الصيانة السنوية']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Hayatt Swimming Pools Maintenance LLC'));
