select 'pools', 'Arabian Pools', 'Arabian Pools', 'أبوظبي', null, '+971 2 557 1631', 'https://arabianpools.com/', null, 'شركة في أبوظبي لإنشاء المسابح وصيانتها وعقود الصيانة السنوية وغرف البخار والساونا.', 'https://arabianpools.com/swimming-pool-maintenance-company-in-abu-dhabi/', 'أرابيان بولز شركة تعمل في أبوظبي في إنشاء المسابح وصيانتها وعقود الصيانة السنوية. تقدم أيضاً غرف البخار والساونا والجاكوزي والنوافير والحمام المغربي وتنسيق الحدائق وتوريد معدات معالجة المياه.', null, 'info@arabianpools.com', null, null, array['إنشاء المسابح', 'عقود الصيانة السنوية', 'غرف البخار والساونا', 'الجاكوزي والسبا', 'النوافير والحمام المغربي']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Arabian Pools'));
