select 'pools', 'Al Mauon General Contracting', 'Al Mauon General Contracting', 'أبوظبي', 'مصفح', '+971 52 340 6916', 'https://almauon.com/', null, 'شركة مقاولات في مصفح بأبوظبي تنفذ المسابح الخرسانية والفايبرجلاس وصيانتها.', 'https://almauon.com/swimming-pool/', 'المعون للمقاولات العامة شركة مقرها مصفح بأبوظبي ولها مكتب في النهدة 2 بدبي وآخر في مسقط. تنفذ المسابح الخرسانية والفايبرجلاس والإنفينيتي وصيانتها، إلى جانب أعمال البناء والكهروميكانيك.', 'https://almauon.com/wp-content/uploads/2024/06/logo-web-2.gif', 'info@almauon.com', 'M-39، مصفح، أبوظبي', null, array['مسابح خرسانية', 'مسابح فايبرجلاس', 'مسابح إنفينيتي ومسابح صغيرة', 'صيانة المسابح وإصلاح التسربات', 'البرجولات ومظلات السيارات']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Al Mauon General Contracting'));
