select 'pools', 'Crystal Pools', 'Crystal Pools', 'أبوظبي', null, '+971 55 223 0049', 'https://mycrystalpool.com/', null, 'شركة تخدم أبوظبي في تصميم المسابح وإنشائها وتنظيفها وصيانتها.', 'https://mycrystalpool.com/en/swimming-pool-company-in-abu-dhabi/', 'كريستال بولز شركة تخدم مناطق أبوظبي وضواحيها. تقدم تصميم المسابح ثنائياً وثلاثياً، وإنشاءها مع العزل، وتنظيفها وصيانة معداتها، والإضاءة والمعالم المائية.', 'https://mycrystalpool.com/wp-content/uploads/2025/03/123-1-1-1.png', 'info@mycrystalpool.com', null, null, array['مسبح داخلي – جزيرة الريم', 'مسبح عائلي – مدينة محمد بن زايد', 'مسبح بشلال – شاطئ الراحة', 'تنظيف وصيانة المسابح', 'إضاءة LED ومعالم مائية']::text[], 'تذكر الشركة أن فريقها من مهندسين معتمدين وفنيين مهرة.', true
where not exists (select 1 from public.service_providers where category = 'pools' and emirate = 'أبوظبي' and lower(coalesce(name_en, name_ar)) = lower('Crystal Pools'));
