select 'car_rental', 'Budget Rent A Car – Ras Al Khaimah (AGMC BMW)', 'Budget Rent A Car – Ras Al Khaimah (AGMC BMW)', 'رأس الخيمة', 'الظيت', '+97148735666', 'https://www.budget-uae.com', null, 'فرع بادجت لتأجير السيارات في رأس الخيمة داخل معرض AGMC BMW بمنطقة الظيت.', 'https://www.budget-uae.com/en/our-locations', 'بادجت لتأجير السيارات في الإمارات امتياز لشركة Budget Rent A Car International، وتملكها مجموعة البطحاء للسيارات الشركة القابضة لـ AGMC. توفر الشركة تأجير السيارات والتأجير طويل الأمد عبر فروع في الدولة منها فرع رأس الخيمة.', 'https://www.budget-uae.com/images/budget-logo-img.png', null, 'شارع الشيخ محمد بن سالم، الظيت، رأس الخيمة', 'https://maps.app.goo.gl/es8D7EmGvmD18hub6', array['تأجير السيارات اليومي', 'تأجير السيارات طويل الأمد (Leasing)']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'car_rental' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('Budget Rent A Car – Ras Al Khaimah (AGMC BMW)'));
insert into public.service_providers (category, name_ar, name_en, emirate, area, phone, website, founded_year, description, source_url, about, logo_url, email, address, map_url, portfolio, team_info, is_active)
select 'legal', 'ATB Legal Consultancy FZ LLC (ATB Legal) – Ras Al Khaimah', 'ATB Legal Consultancy FZ LLC (ATB Legal) – Ras Al Khaimah', 'رأس الخيمة', 'المنطقة الحرة لرأس الخيمة (RAKEZ)', '+97172042414', 'https://atblegal.com', null, 'مكتب استشارات قانونية له مكتب في رأس الخيمة يقدم خدمات النزاعات والشركات والملكية الفكرية بين الإمارات والهند.', 'https://atblegal.com/about-us/', 'ATB Legal استشارات قانونية تعمل في القضايا العابرة للحدود والشؤون التجارية بين الإمارات والهند، ولها مكاتب في أبوظبي ورأس الخيمة وبنغالور. تذكر أنها مسجلة أمام محاكم مركز دبي المالي العالمي وسوق أبوظبي العالمي، وتتعاون مع مكاتب إماراتية في قضايا البر الرئيسي.', null, 'offices@atblegal.com', 'مركز الأعمال 04، المنطقة الاقتصادية لرأس الخيمة (راكز)، ص.ب 17212، رأس الخيمة', null, array['تسوية النزاعات والتحكيم', 'قانون العمل', 'الشركات والتجارة', 'الأحوال الشخصية والوصايا', 'الملكية الفكرية والعلامات التجارية']::text[], 'يذكر الموقع أن محاميه يمارسون المهنة منذ نحو عقدين لكلٍّ منهم.', true
where not exists (select 1 from public.service_providers where category = 'legal' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('ATB Legal Consultancy FZ LLC (ATB Legal) – Ras Al Khaimah'));
