select 'engineering', 'ACE – Al Ain Consulting Engineers (Al Ain Office)', 'ACE – Al Ain Consulting Engineers (Al Ain Office)', 'العين', 'شارع خليفة', '+97137643117', 'https://ace-uae.net', null, 'استشاري هندسي ومعماري متعدد التخصصات افتتح أول مكاتبه في العين عام 1975.', 'https://ace-uae.net/contact-us/', 'ACE استشارات معمارية وهندسية متعددة التخصصات تشمل العمارة والهندسة الإنشائية والكهروميكانيكية والإشراف على المواقع والاستدامة والتخطيط العمراني. افتتحت أول مكتب لها في العين عام 1975 ثم أبوظبي ورأس الخيمة والشارقة، وتحمل شهادات ISO 9001 و14001 و45001.', 'https://ace-uae.net/wp-content/uploads/2025/04/logo.png', 'info@ace-uae.net', 'الطابق الأول، بناية سعيد الكويتي، شارع خليفة، العين', 'https://maps.app.goo.gl/wxuDHathBcNxvjyi6', array['التصميم المعماري', 'الهندسة الإنشائية والكهروميكانيكية', 'الإشراف على المواقع', 'استشارات الاستدامة', 'التخطيط العمراني']::text[], 'يذكر الموقع أن إجمالي عدد مهندسيه 1500 مهندس.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'العين' and lower(coalesce(name_en, name_ar)) = lower('ACE – Al Ain Consulting Engineers (Al Ain Office)'));
