select 'engineering', 'ACE – Al Ain Consulting Engineers (Ras Al Khaimah Office)', 'ACE – Al Ain Consulting Engineers (Ras Al Khaimah Office)', 'رأس الخيمة', 'شارع حصوم', '+97137643117', 'https://ace-uae.net', null, 'مكتب رأس الخيمة لشركة ACE للاستشارات الهندسية والمعمارية، افتُتح عام 2004.', 'https://ace-uae.net/contact-us/', 'مكتب رأس الخيمة تابع لشركة ACE للاستشارات المعمارية والهندسية التي بدأت في العين عام 1975، وقد افتُتح عام 2004 بحسب الموقع. تقدم الشركة خدمات التصميم والهندسة والإشراف والاستدامة.', 'https://ace-uae.net/wp-content/uploads/2025/04/logo.png', 'info@ace-uae.net', 'مكتب رقم 07، شارع حصوم، رأس الخيمة', 'https://maps.app.goo.gl/xJ39sfbaa7SmMXKr7?g_st=iw', array['التصميم المعماري', 'الهندسة الإنشائية والكهروميكانيكية', 'الإشراف على المواقع']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('ACE – Al Ain Consulting Engineers (Ras Al Khaimah Office)'));
