select 'engineering', 'Al-Nakheel Engineering Consultants', 'Al-Nakheel Engineering Consultants', 'عجمان', 'النخيل', '+97167457929', 'https://alnakheelconsultants.com', 1995, 'مكتب استشارات هندسية في عجمان منذ 1995 متخصص في تصميم المباني والإشراف على تنفيذها.', 'https://alnakheelconsultants.com/', 'النخيل للاستشارات الهندسية مكتب تصميم وإشراف إنشائي مقره عجمان تأسس عام 1995. يقدم مخططات الفلل والمباني والمراكز التجارية والتفتيش الهندسي ومتابعة التنفيذ، ويذكر أنه أنجز أكثر من 2000 مشروع منذ تأسيسه.', 'https://alnakheelconsultants.com/img/logo1.png', 'info@alnakheelconsultants.com', 'شارع النخيل، مقابل مسجد الفرقان، ص.ب 2476، عجمان', 'https://maps.google.com/?cid=13197978867997039035', array['تصميم الفلل والمباني السكنية', 'تصميم المستودعات والمعارض', 'الإشراف الهندسي على المواقع']::text[], 'بدأ المكتب بمهندسَين اثنين ويضم اليوم 22 موظفاً بحسب الموقع.', true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Al-Nakheel Engineering Consultants'));
