select 'engineering', 'Bu Humaid Engineering Consultants', 'Bu Humaid Engineering Consultants', 'عجمان', 'النعيمية', '+97167468222', 'https://buhumaidco.com', null, 'مكتب استشارات هندسية في عجمان تابع لمجموعة بو حميد، يقدم إدارة المشاريع والاستشارات.', 'https://buhumaidco.com/about.html', 'أُسس مكتب بو حميد للاستشارات الهندسية بعد عامين من تأسيس شركة بو حميد للمقاولات (1983) في عجمان. يقدم إدارة البرامج والمشاريع واستشارات التكاليف وإدارة المرافق.', null, 'info@buhumaidco.com', 'شارع الملك فيصل، النعيمية، ص.ب 5755، عجمان', null, array['فندق ويندهام جاردن عجمان (استشارات)', 'إدارة البرامج والمشاريع', 'استشارات التكاليف']::text[], null, true
where not exists (select 1 from public.service_providers where category = 'engineering' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Bu Humaid Engineering Consultants'));
