select 'contracting', 'Bu Humaid Contracting Company', 'Bu Humaid Contracting Company', 'عجمان', 'النعيمية', '+97167468222', 'https://buhumaidco.com', 1983, 'شركة مقاولات في عجمان منذ 1983 نفذت مباني تجارية وسكنية وفللاً ومستودعات ومساجد.', 'https://buhumaidco.com/about.html', 'بدأت شركة بو حميد للمقاولات عام 1983 في عجمان في مجال الإنشاءات الهندسية وإدارتها. تذكر أنها أنجزت مئات المشاريع الحكومية والخاصة من مبانٍ تجارية وسكنية وفلل ومستودعات ومساجد وأعمال صيانة.', null, 'info@buhumaidco.com', 'شارع الملك فيصل، النعيمية، ص.ب 5755، عجمان', null, array['مبانٍ تجارية وسكنية', 'فلل', 'مستودعات', 'مساجد', 'أعمال صيانة']::text[], 'رئيس مجلس الإدارة المهندس عماد الدين أحمد صبح.', true
where not exists (select 1 from public.service_providers where category = 'contracting' and emirate = 'عجمان' and lower(coalesce(name_en, name_ar)) = lower('Bu Humaid Contracting Company'));
