select 'contracting', 'Al Nuaimi Group LLC', 'Al Nuaimi Group LLC', 'رأس الخيمة', null, '+97172223999', 'https://alnuaimi-group.com', 1974, 'مجموعة مقاولات في رأس الخيمة منذ 1974 تعمل في الطرق والبنية التحتية والإنشاءات العامة.', 'https://alnuaimi-group.com/about/', 'أسس عبدالله أحمد راشد النعيمي مجموعة النعيمي عام 1974 في رأس الخيمة. تعمل المجموعة في الطرق والبنية التحتية والإنشاءات العامة والأساسات والخرسانة الجاهزة والأعمال الكهروميكانيكية والألمنيوم والزجاج، وتحمل شهادات ISO 9001 و14001 و45001.', 'https://alnuaimi-group.com/wp-content/uploads/2025/04/logo.png', 'info@alnuaimi-group.com', 'ص.ب 3، رأس الخيمة', null, array['الطرق والبنية التحتية', 'الإنشاءات العامة', 'الخوازيق والأساسات', 'الخرسانة الجاهزة', 'الأعمال الكهروميكانيكية والجهد العالي']::text[], 'المؤسس عبدالله أحمد راشد النعيمي، والرئيس التنفيذي د. راشد النعيمي.', true
where not exists (select 1 from public.service_providers where category = 'contracting' and emirate = 'رأس الخيمة' and lower(coalesce(name_en, name_ar)) = lower('Al Nuaimi Group LLC'));
